import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [resorts, setResorts] = useState([]);
  const [query, setQuery] = useState('');
  const [filteredResorts, setFilteredResorts] = useState([]);

  useEffect(() => {
    async function fetchResorts() {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/ski-resorts`);
        setResorts(response.data);
      } catch (error) {
        console.error('Error fetching resorts:', error);
      }
    }
    fetchResorts();
  }, []);

  useEffect(() => {
    if (query) {
      setFilteredResorts(resorts.filter(resort => resort.name.toLowerCase().includes(query.toLowerCase())));
    } else {
      setFilteredResorts(resorts);
    }
  }, [query, resorts]);

  return (
    <div>
      <h1>Ski Resorts</h1>
      <input
        type="text"
        placeholder="Search for a resort..."
        value={query}
        onChange={e => setQuery(e.target.value)}
      />
      <ul>
        {filteredResorts.map(resort => (
          <li key={resort.slug}>{resort.name}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;
